using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;

namespace ZFrame.View
{
    /// <summary>
    /// Settings panel view (TASK-A-M3-02), assembled exactly like the
    /// TASK-A-M3-01 sample panel: prefab generated by
    /// <c>ZFrame.View.SettingsUiSetup</c> at
    /// <c>Assets/UI/Resources/ui_settings_panel.prefab</c> (resource key
    /// "ui_settings_panel", <see cref="DefaultConfig"/>), registered in
    /// <see cref="UIBinding.EnsureDefaults"/>, pushed through
    /// <see cref="UIManager"/>.
    ///
    /// The frame (title, tab bar host, row host, the three bottom buttons) is
    /// prefab content; EVERYTHING per page is generated at open time:
    /// tab buttons from <see cref="SettingsRegistry.Pages"/>, rows from each
    /// page's definitions through <see cref="SettingsRowFactory"/> — the view
    /// holds no hardcoded option layout (加选项不改布局).
    ///
    /// The view only raises intents as C# events; the
    /// <see cref="SettingsPanelPresenter"/> decides semantics (snapshot /
    /// revert / reset / save / close). Esc closes through
    /// <see cref="RequestClose"/> (polls legacy Input in play mode; the
    /// presenter treats Esc as CANCEL: revert then close, never save).
    ///
    /// TASK-A-M3-03: the 操作 tab's rows talk to the injected
    /// <see cref="IBindingSettings"/> (from <see cref="SettingsPanelArgs"/>)
    /// and write their rebind feedback into a status line the view appends to
    /// every generated page (Toast 文本行 — one extra generated child, still
    /// zero hand-written layout).
    /// </summary>
    public sealed class SettingsPanelView : UIViewBase
    {
        /// <summary>Default config: blocking Panel-layer panel with a fade-in, no instance cache (rows rebuild fresh every open).</summary>
        public static PanelConfig DefaultConfig { get; } = PanelConfig.Create(
            prefabKey: "ui_settings_panel",
            layer: UIConsts.UILayer.Panel,
            blockMask: true,
            animIn: PanelAnim.Fade);

        [SerializeField] private Text _titleText;
        [SerializeField] private RectTransform _tabBar;
        [SerializeField] private RectTransform _rowHost;
        [SerializeField] private Button _applyButton;
        [SerializeField] private Button _revertButton;
        [SerializeField] private Button _resetButton;

        private SettingsModel _model;
        private IBindingSettings _bindings;
        private GameObject _pageContainer;
        private Text _statusText;
        private bool _buttonsWired;

        /// <summary>A row control committed a new value (definition, value) — presenter forwards to <see cref="SettingsModel.Set{T}"/>.</summary>
        public event Action<SettingDefinition, object> SettingChanged;

        /// <summary>Bottom "应用并关闭" pressed.</summary>
        public event Action ApplyRequested;

        /// <summary>Bottom "撤销更改" pressed.</summary>
        public event Action RevertRequested;

        /// <summary>Bottom "恢复默认" pressed.</summary>
        public event Action ResetRequested;

        /// <summary>Esc (or any close request) — the presenter treats this as cancel: revert, then close, never save.</summary>
        public event Action CloseRequested;

        /// <summary>Title text (presenter sets the header; tests assert on it).</summary>
        public string TitleText => _titleText != null ? _titleText.text : null;

        /// <summary>Number of row GameObjects currently generated for the active page (the feedback line is not a row).</summary>
        public int RowCount => _pageContainer != null
            ? _pageContainer.transform.childCount - (_statusText != null ? 1 : 0)
            : 0;

        /// <summary>Number of generated tab buttons (= page count of the bound registry).</summary>
        public int TabCount => _tabBar != null ? _tabBar.childCount : 0;

        /// <summary>Id of the page currently displayed (null before first selection).</summary>
        public string CurrentPageId { get; private set; }

        /// <summary>The bound model (null when pushed without <see cref="SettingsPanelArgs"/>).</summary>
        public SettingsModel Model => _model;

        /// <summary>The injected binding backend of the 操作 tab (null = binding rows disabled).</summary>
        public IBindingSettings Bindings => _bindings;

        /// <summary>Current text of the page's feedback line (Toast 文本行); empty before the first feedback.</summary>
        public string StatusText => _statusText != null ? _statusText.text : null;

        /// <summary>Exposed for tests/programmatic entry (same discipline as the sample panel's TestButton getter).</summary>
        public Button ApplyButton => _applyButton;

        /// <summary>Exposed for tests.</summary>
        public Button RevertButton => _revertButton;

        /// <summary>Exposed for tests.</summary>
        public Button ResetButton => _resetButton;

        /// <summary>Exposed for tests: transform the generated page container is parented to.</summary>
        public Transform RowHost => _rowHost;

        public override void OnInit(object args)
        {
            SettingsPanelArgs panelArgs = args as SettingsPanelArgs;
            _model = panelArgs?.Model;
            _bindings = panelArgs?.Bindings;

            WireButtonsOnce();

            // Fresh page content on every open (rows are rebuilt from the registry —
            // never cached, so added definitions appear without touching layout code).
            ClearChildren(_tabBar);
            if (_pageContainer != null)
            {
                DestroyObject(_pageContainer);
                _pageContainer = null;
            }

            BuildTabButtons();

            if (_model != null && _model.Registry.Pages.Count > 0)
            {
                SelectPage(_model.Registry.Pages[0].Id);
            }
        }

        protected override void OnViewDestroy()
        {
            if (_buttonsWired && _applyButton != null)
            {
                _applyButton.onClick.RemoveListener(RaiseApplyRequested);
                _revertButton.onClick.RemoveListener(RaiseRevertRequested);
                _resetButton.onClick.RemoveListener(RaiseResetRequested);
                _buttonsWired = false;
            }

            SettingChanged = null;
            ApplyRequested = null;
            RevertRequested = null;
            ResetRequested = null;
            CloseRequested = null;
        }

        /// <summary>Rebuilds the active page's rows (called after model-side Revert/Reset so controls show restored values).</summary>
        public void RefreshRows()
        {
            if (CurrentPageId != null)
            {
                SelectPage(CurrentPageId);
            }
        }

        /// <summary>
        /// Switches the displayed page: destroys the generated page container
        /// and regenerates every row of <paramref name="pageId"/> through
        /// <see cref="SettingsRowFactory"/> — the data-driven core of the panel.
        /// </summary>
        public void SelectPage(string pageId)
        {
            if (_model == null || !_model.Registry.TryGetPage(pageId, out SettingsPage page))
            {
                Debug.LogWarning($"[SettingsPanel] unknown settings page '{pageId}'.");
                return;
            }

            if (_pageContainer != null)
            {
                DestroyObject(_pageContainer);
                _pageContainer = null;
            }

            _pageContainer = SettingsRowFactory.CreatePageContainer(_rowHost);
            bool hasBindingRows = false;
            foreach (SettingDefinition definition in page.Settings)
            {
                hasBindingRows |= definition.Type == SettingType.Binding;
                SettingsRowFactory.CreateRow(
                    definition,
                    _pageContainer.transform,
                    OnRowValueChanged,
                    _bindings,
                    SetStatus);
            }

            // Feedback line at the bottom of the 操作 page (Toast 文本行) —
            // generated, never hand-placed, and cleared on every page switch.
            // Pages without binding rows get no extra empty line.
            _statusText = hasBindingRows
                ? SettingsRowFactory.CreateStatusLine(_pageContainer.transform).GetComponent<Text>()
                : null;

            CurrentPageId = pageId;
        }

        /// <summary>Writes the 操作 tab's feedback line (rebind outcome / conflict / reset notice).</summary>
        public void SetStatus(string message)
        {
            if (_statusText != null)
            {
                _statusText.text = message ?? string.Empty;
            }
        }

        /// <summary>
        /// Re-reads every Binding row's key caption from the injected backend.
        /// Used after 全部恢复默认: the rows are NOT rebuilt (destroying the
        /// clicked button mid-click is unsafe in EditMode), only their captions
        /// are refreshed from the authoritative display strings.
        /// </summary>
        public void RefreshBindingCaptions()
        {
            if (_pageContainer == null || _bindings == null || _model == null)
            {
                return;
            }

            foreach (Transform row in _pageContainer.transform)
            {
                if (!row.name.StartsWith(SettingsRowFactory.RowNamePrefix, StringComparison.Ordinal))
                {
                    continue;
                }

                string settingId = row.name.Substring(SettingsRowFactory.RowNamePrefix.Length);
                if (!_model.Registry.TryGetDefinition(settingId, out SettingDefinition definition) ||
                    definition.Type != SettingType.Binding)
                {
                    continue;
                }

                Transform label = row.Find(SettingsRowFactory.KeyButtonName + "/" + SettingsRowFactory.ButtonLabelName);
                Text caption = label != null ? label.GetComponent<Text>() : null;
                if (caption != null)
                {
                    // 每行只刷新自己那个 binding（A-M3-04：移动四向共用 Player/Move，
                    // 少了索引四行都会显示主绑定 W）。
                    caption.text = _bindings.GetBindingDisplay(definition.ActionKey, definition.BindingIndex);
                }
            }
        }

        /// <summary>
        /// Row → presenter forwarding. Binding-reset rows additionally refresh
        /// the key captions in place (they already dropped the overrides), so
        /// the page shows the restored keys without a rebuild.
        /// </summary>
        private void OnRowValueChanged(SettingDefinition definition, object value)
        {
            if (definition != null && definition.Type == SettingType.BindingReset)
            {
                RefreshBindingCaptions();
            }

            SettingChanged?.Invoke(definition, value);
        }

        /// <summary>Raises <see cref="CloseRequested"/> (Esc path; tests call this directly — Input polling never runs in EditMode).</summary>
        public void RequestClose()
        {
            CloseRequested?.Invoke();
        }

        /// <summary>Sets the panel header (presenter-driven, like the sample panel's status text).</summary>
        public void SetTitle(string title)
        {
            if (_titleText != null)
            {
                _titleText.text = title;
            }
        }

        /// <summary>Play-mode only: Esc cancels the panel (see class doc for the cancel semantics).</summary>
        private void Update()
        {
            if (Input.GetKeyDown(KeyCode.Escape))
            {
                RequestClose();
            }
        }

        private void WireButtonsOnce()
        {
            if (_buttonsWired)
            {
                return;
            }

            if (_applyButton != null)
            {
                _applyButton.onClick.AddListener(RaiseApplyRequested);
                _revertButton.onClick.AddListener(RaiseRevertRequested);
                _resetButton.onClick.AddListener(RaiseResetRequested);
                _buttonsWired = true;
            }
        }

        private void RaiseApplyRequested()
        {
            ApplyRequested?.Invoke();
        }

        private void RaiseRevertRequested()
        {
            RevertRequested?.Invoke();
        }

        private void RaiseResetRequested()
        {
            ResetRequested?.Invoke();
        }

        private void BuildTabButtons()
        {
            if (_model == null || _tabBar == null)
            {
                return;
            }

            foreach (SettingsPage page in _model.Registry.Pages)
            {
                string pageId = page.Id;
                var tabGo = new GameObject("Tab_" + pageId, typeof(RectTransform));
                tabGo.GetComponent<RectTransform>().SetParent(_tabBar, false);
                LayoutElement element = tabGo.AddComponent<LayoutElement>();
                element.preferredHeight = 56f;
                element.preferredWidth = 160f;

                Image image = tabGo.AddComponent<Image>();
                image.color = new Color(0.25f, 0.28f, 0.35f);
                Button button = tabGo.AddComponent<Button>();

                var labelGo = new GameObject("Text", typeof(RectTransform));
                RectTransform labelRect = labelGo.GetComponent<RectTransform>();
                labelRect.SetParent(tabGo.transform, false);
                labelRect.anchorMin = Vector2.zero;
                labelRect.anchorMax = Vector2.one;
                labelRect.offsetMin = Vector2.zero;
                labelRect.offsetMax = Vector2.zero;
                Text label = labelGo.AddComponent<Text>();
                label.font = Resources.GetBuiltinResource<Font>("LegacyRuntime.ttf");
                label.fontSize = 32;
                label.alignment = TextAnchor.MiddleCenter;
                label.color = Color.white;
                label.raycastTarget = false;
                label.text = page.DisplayName;

                button.onClick.AddListener(() => SelectPage(pageId));
            }
        }

        /// <summary>Destroys all children of a host (play mode: Destroy; edit mode: DestroyImmediate, per UIManager's precedent).</summary>
        private static void ClearChildren(Transform host)
        {
            if (host == null)
            {
                return;
            }

            for (int i = host.childCount - 1; i >= 0; i--)
            {
                DestroyObject(host.GetChild(i).gameObject);
            }
        }

        /// <summary>Destroy helper (same discipline as UIManager): play mode defers with Object.Destroy, edit mode destroys immediately.</summary>
        private static void DestroyObject(GameObject instance)
        {
            if (Application.isPlaying)
            {
                UnityEngine.Object.Destroy(instance);
            }
            else
            {
                UnityEngine.Object.DestroyImmediate(instance);
            }
        }
    }
}
